func NewCounter() (inc func(), value func() int) {
    var mu sync.Mutex
    n := 0
    inc = func() { mu.Lock(); n++; mu.Unlock() }
    value = func() int { mu.Lock(); defer mu.Unlock(); return n }
    return inc, value
}

// consumer
inc, value := NewCounter()
inc()
fmt.Println(value())
